package vn.smarttravel.catalog.places.repository;

import java.util.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;

@Repository
public class BusinessRepository {
    private final JdbcTemplate db;private final CatalogRepository catalog;private final ObjectMapper json;
    public BusinessRepository(JdbcTemplate db,CatalogRepository catalog,ObjectMapper json){this.db=db;this.catalog=catalog;this.json=json;}
    @Transactional public Map<String,Object> create(UUID user,Map<String,Object> body){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,user);
        UUID id=UUID.randomUUID();String name=Objects.toString(body.getOrDefault("display_name",body.get("name")),"").trim();if(name.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Display name required");
        db.update("INSERT INTO catalog.businesses(business_id,owner_user_id,display_name,legal_name,contact_email,contact_phone) VALUES(?,?,?,?,?,?)",id,user,name,body.get("legal_name"),body.get("contact_email"),body.get("contact_phone"));
        db.update("INSERT INTO catalog.business_members(business_id,user_id,member_role) VALUES(?,?,'OWNER')",id,user);return business(id);
    }
    public Map<String,Object> business(UUID id){var rows=db.queryForList("SELECT * FROM catalog.businesses WHERE business_id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return rows.getFirst();}
    private void membership(UUID business,UUID user,boolean verified){
        var rows=db.queryForList("SELECT b.verification_status FROM catalog.businesses b JOIN catalog.business_members m USING(business_id) WHERE b.business_id=? AND m.user_id=? AND m.active FOR UPDATE OF b,m",business,user);
        if(rows.isEmpty()||(verified&&!rows.getFirst().get("verification_status").equals("VERIFIED")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Business membership or verification required");
    }
    private void owner(UUID business,UUID user){var rows=db.queryForList("SELECT owner_user_id FROM catalog.businesses WHERE business_id=? FOR UPDATE",business);if(rows.isEmpty()||!user.equals(rows.getFirst().get("owner_user_id")))throw new ResponseStatusException(HttpStatus.NOT_FOUND);}
    public List<Map<String,Object>> list(UUID user){return db.queryForList("SELECT b.* FROM catalog.businesses b JOIN catalog.business_members m USING(business_id) WHERE m.user_id=? AND m.active ORDER BY business_id",user);}
    public Map<String,Object> get(UUID business,UUID user){membership(business,user,false);return business(business);}
    @Transactional public Map<String,Object> update(UUID business,UUID user,long version,Map<String,Object> body){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,user);owner(business,user);if(db.update("UPDATE catalog.businesses SET display_name=coalesce(?,display_name),version=version+1,updated_at=now() WHERE business_id=? AND version=?",body.get("name"),business,version)!=1)throw new ResponseStatusException(HttpStatus.CONFLICT);return business(business);}
    @Transactional public void delete(UUID business,UUID user,long version){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,user);owner(business,user);if(db.update("UPDATE catalog.businesses SET verification_status='SUSPENDED',version=version+1,updated_at=now() WHERE business_id=? AND version=?",business,version)!=1)throw new ResponseStatusException(HttpStatus.CONFLICT);db.update("UPDATE catalog.business_place_claims SET status='REVOKED',version=version+1 WHERE business_id=?",business);}
    public List<Map<String,Object>> members(UUID business,UUID user){membership(business,user,false);return db.queryForList("SELECT * FROM catalog.business_members WHERE business_id=? AND active ORDER BY member_id",business);}
    public Map<String,Object> member(UUID business,UUID member,UUID user){membership(business,user,false);var rows=db.queryForList("SELECT * FROM catalog.business_members WHERE business_id=? AND member_id=? AND active",business,member);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return rows.getFirst();}
    @Transactional public Map<String,Object> ownMembership(UUID business,UUID user,String role){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,user);owner(business,user);if(!"OWNER".equals(role))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Owner membership cannot be demoted");return db.queryForList("SELECT * FROM catalog.business_members WHERE business_id=? AND user_id=?",business,user).getFirst();}
    @Transactional public Map<String,Object> memberUpdate(UUID business,UUID member,UUID user,long version,String role){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,user);owner(business,user);var current=member(business,member,user);if(current.get("user_id").equals(user)&&!"OWNER".equals(role))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Owner cannot be demoted");if(db.update("UPDATE catalog.business_members SET member_role=?,version=version+1 WHERE business_id=? AND member_id=? AND version=? AND active",role,business,member,version)!=1)throw new ResponseStatusException(HttpStatus.CONFLICT);return member(business,member,user);}
    @Transactional public void memberDelete(UUID business,UUID member,UUID user,long version){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,user);owner(business,user);var row=member(business,member,user);if(row.get("user_id").equals(user))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Owner cannot be removed");if(db.update("UPDATE catalog.business_members SET active=false,version=version+1 WHERE business_id=? AND member_id=? AND version=?",business,member,version)!=1)throw new ResponseStatusException(HttpStatus.CONFLICT);}
    @Transactional public Map<String,Object> verification(UUID business,UUID user,List<String> evidence){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,user);owner(business,user);if(evidence==null||evidence.isEmpty()||evidence.stream().anyMatch(k->!k.startsWith("private/")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Private evidence required");UUID id=UUID.randomUUID();try{db.update("INSERT INTO catalog.business_verifications(request_id,business_id,evidence_keys,submitted_by) VALUES(?,?,?::jsonb,?)",id,business,json.writeValueAsString(evidence),user);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalArgumentException(e);}return Map.of("request_id",id,"status","PENDING","version",1L);}
    @Transactional public Map<String,Object> verificationReview(UUID request,UUID admin,String action,String reason){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,admin);var rows=db.queryForList("SELECT * FROM catalog.business_verifications WHERE request_id=? FOR UPDATE",request);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var row=rows.getFirst();if(!"PENDING".equals(row.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT);if(reason==null||reason.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST);String state=switch(action){case "APPROVE"->"APPROVED";case "REJECT"->"REJECTED";case "REVOKE"->"REVOKED";default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST);};UUID business=(UUID)row.get("business_id");var b=business(business);verify(business,((Number)b.get("version")).longValue(),action.equals("APPROVE")?"VERIFIED":action.equals("REJECT")?"REJECTED":"SUSPENDED");db.update("UPDATE catalog.business_verifications SET status=?,version=version+1,reviewed_by=?,reason=? WHERE request_id=?",state,admin,reason,request);return Map.of("request_id",request,"status","COMPLETED","version",((Number)row.get("version")).longValue()+1);}
    @Transactional public Map<String,Object> verify(UUID id,long version,String status){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquireAuthenticated(db);
        if(!Set.of("VERIFIED","REJECTED","SUSPENDED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);
        if(db.update("UPDATE catalog.businesses SET verification_status=?,version=version+1,updated_at=now() WHERE business_id=? AND version=?",status,id,version)==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Version conflict");return business(id);
    }
    @Transactional public Object claim(UUID business,UUID user,Map<String,Object> body){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,user);
        membership(business,user,true);UUID id=UUID.randomUUID();UUID place=UUID.fromString(body.get("place_id").toString());catalog.place(place,false);
        String evidence=body.get("evidence_keys") instanceof List<?> keys&&!keys.isEmpty()?keys.getFirst().toString():Objects.toString(body.get("evidence_object_key"),"");if(!evidence.startsWith("private/"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Private evidence required");
        db.update("INSERT INTO catalog.business_place_claims(claim_id,business_id,place_id,claim_role,evidence_object_key) VALUES(?,?,?,?,?)",id,business,place,body.getOrDefault("claim_role","OWNER"),evidence);return Map.of("claim_id",id,"business_id",business,"place_id",place,"owner_user_id",user,"status","PENDING","version",1L);
    }
    @Transactional public Object reviewClaim(UUID id,UUID reviewer,String status,String reason){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,reviewer);
        if(!Set.of("APPROVED","REJECTED","REVOKED").contains(status)||reason==null||reason.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST);
        var rows=db.queryForList("SELECT c.*,b.owner_user_id,b.verification_status FROM catalog.business_place_claims c JOIN catalog.businesses b USING(business_id) WHERE c.claim_id=? FOR UPDATE OF c,b",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var claim=rows.getFirst();
        if(status.equals("APPROVED")&&!claim.get("verification_status").equals("VERIFIED"))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Unverified business");
        db.update("UPDATE catalog.business_place_claims SET status=?,reviewed_by=?,reviewed_at=now(),reason=?,version=version+1 WHERE claim_id=?",status,reviewer,reason,id);long version=((Number)claim.get("version")).longValue()+1;
        catalog.emit("catalog.business-claim.reviewed.v1",id,version,Map.of("claim_id",id,"business_id",claim.get("business_id"),"place_id",claim.get("place_id"),"owner_user_id",claim.get("owner_user_id"),"status",status,"version",version));return Map.of("claim_id",id,"status",status);
    }
    @Transactional public Object request(UUID claimId,UUID user,long expected,Map<String,Object> fields){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,user);
        var claims=db.queryForList("SELECT * FROM catalog.business_place_claims WHERE claim_id=? AND status='APPROVED' FOR UPDATE",claimId);if(claims.isEmpty())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Approved claim required");var claim=claims.getFirst();membership((UUID)claim.get("business_id"),user,true);
        if(fields.isEmpty()||!Set.of("name","category_ids","latitude","longitude","opening_hours","price","currency","name_vi","name_en","description","address","price_min","price_max").containsAll(fields.keySet()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported fields");
        String data;try{data=json.writeValueAsString(fields);}catch(Exception e){throw new IllegalArgumentException(e);}UUID id=UUID.randomUUID();db.update("INSERT INTO catalog.change_requests(request_id,claim_id,place_id,submitted_by,expected_place_version,field_changes) VALUES(?,?,?,?,?,?::jsonb)",id,claimId,claim.get("place_id"),user,expected,data);return Map.of("request_id",id,"change_request_id",id,"claim_id",claimId,"fields",fields,"expected_version",expected,"status","PENDING","version",1L);
    }
    @Transactional public Object reviewRequest(UUID request,UUID admin,String decision,String reason){vn.smarttravel.catalog.infrastructure.persistence.repository.UserMutationFence.acquire(db,admin);
        var rows=db.queryForList("SELECT r.*,c.business_id,c.status claim_status FROM catalog.change_requests r JOIN catalog.business_place_claims c USING(claim_id,place_id) WHERE request_id=? FOR UPDATE OF r,c",request);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var row=rows.getFirst();
        if(!row.get("status").equals("PENDING"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Already reviewed");
        if(reason==null||reason.isBlank()||!Set.of("APPROVED","REJECTED").contains(decision))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);
        if(decision.equals("APPROVED")){
            membership((UUID)row.get("business_id"),(UUID)row.get("submitted_by"),true);
            if(!row.get("claim_status").equals("APPROVED"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Claim revoked");
            long expected=((Number)row.get("expected_place_version")).longValue();UUID place=(UUID)row.get("place_id");
            long actual=db.queryForObject("SELECT version FROM catalog.places WHERE place_id=? FOR UPDATE",Long.class,place);
            if(actual!=expected)decision="CONFLICT";else{try{@SuppressWarnings("unchecked")Map<String,Object> fields=json.readValue(row.get("field_changes").toString(),Map.class);catalog.updateAtPriority(place,expected,fields,admin,3);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}}
        }
        db.update("UPDATE catalog.change_requests SET status=?,reviewed_by=?,reviewed_at=now(),reason=?,version=version+1 WHERE request_id=?",decision,admin,reason,request);return Map.of("request_id",request,"status",decision);
    }
}
